// Cloudflare Workers entry point (see wrangler.jsonc "main").
//
// Wraps the worker generated by `opennextjs-cloudflare build` in
// .open-next/worker.js. See replit.md → "Cloudflare Workers".
import openNextWorker from "./.open-next/worker.js";

// Durable Object used by the ISR revalidation queue (wrangler.jsonc).
export { DOQueueHandler } from "./.open-next/worker.js";

// Next.js registers its "router server" helpers (render404, nextConfig, ...)
// on globalThis under a key derived from the project directory, and each page
// looks them up under the key baked in at build time (""). Inside Workers the
// two keys differ (".." vs ""), so a page whose getStaticProps returns
// `notFound` (every unknown URL, through Faust's catch-all route) answered
// with a bare "This page could not be found" text instead of pages/404.js.
// Resolve the build-time key to whatever entry Next.js registered.
const ROUTER_SERVER_METHODS = Symbol.for("@next/router-server-methods");

function linkRouterServerContext() {
  const registry = (globalThis[ROUTER_SERVER_METHODS] ??= {});
  if (Object.getOwnPropertyDescriptor(registry, "")) return;
  Object.defineProperty(registry, "", {
    configurable: true,
    enumerable: false,
    get() {
      const key = Object.keys(this)[0];
      return key === undefined ? undefined : this[key];
    },
    // If Next.js itself registers under "" (keys already match), keep its
    // value as a plain property.
    set(value) {
      Object.defineProperty(this, "", {
        configurable: true,
        enumerable: true,
        writable: true,
        value,
      });
    },
  });
}

linkRouterServerContext();

export default {
  fetch(request, env, ctx) {
    return openNextWorker.fetch(request, env, ctx);
  },
};
